1	package logfile
2	
3	import (
4		"encoding/binary"
5		"fmt"
6		"hash/crc32"
7		"os"
8		"path/filepath"
9		"sync"
10	
11		"github.com/cocosolocoder/signalroom/internal/metrics"
12	)
13	
14	// metricsLogName is the append-only batch log for metric samples. It sits
15	// next to events.log in the locked data directory and uses the same
16	// length-prefixed, CRC-checked frame layout, so the durability and recovery
17	// rules are identical: fsync before acknowledging, trim only a torn tail,
18	// and refuse to start on any other corruption.
19	const metricsLogName = "metrics.log"
20	
21	// MetricsLog is the concurrency-safe durable writer for metric batches. It is
22	// independent from both the event and incident logs: a metric write failure
23	// poisons only metric handling, leaving events and incidents available.
24	type MetricsLog struct {
25		mu       sync.Mutex
26		file     *os.File
27		dir      string
28		poisoned bool
29	}
30	
31	// OpenMetricsLog opens (creating if absent) the metrics log inside an
32	// already-locked data directory, replays its batches, and truncates at most
33	// one incomplete trailing frame. A corrupt frame in the middle, or a complete
34	// frame containing illegal data, is fatal and leaves the file untouched.
35	// Call it only after Open has acquired the directory lock.
36	func OpenMetricsLog(dir string) (*MetricsLog, [][]metrics.Sample, error) {
37		if dir == "" {
38			return nil, nil, fmt.Errorf("data directory is required")
39		}
40		path := filepath.Join(dir, metricsLogName)
41		file, err := os.OpenFile(path, os.O_CREATE|os.O_RDWR|os.O_APPEND, 0o644)
42		if err != nil {
43			return nil, nil, fmt.Errorf("open metrics log: %w", err)
44		}
45	
46		batches, validLen, err := replayMetrics(file)
47		if err != nil {
48			file.Close()
49			return nil, nil, err
50		}
51		if info, statErr := file.Stat(); statErr == nil && validLen < info.Size() {
52			// Drop exactly one incomplete trailing frame; the only mutation
53			// recovery performs, fsynced before serving.
54			if err := file.Truncate(validLen); err != nil {
55				file.Close()
56				return nil, nil, fmt.Errorf("truncate incomplete trailing metric frame: %w", err)
57			}
58			if err := file.Sync(); err != nil {
59				file.Close()
60				return nil, nil, fmt.Errorf("sync metrics log: %w", err)
61			}
62			if err := syncDir(dir); err != nil {
63				file.Close()
64				return nil, nil, fmt.Errorf("sync data directory: %w", err)
65			}
66		}
67	
68		return &MetricsLog{file: file, dir: dir}, batches, nil
69	}
70	
71	// replayMetrics scans the log and returns the valid batches, the byte offset
72	// at which the log is known good, and an error for any corruption before that
73	// offset.
74	func replayMetrics(file *os.File) ([][]metrics.Sample, int64, error) {
75		data, err := os.ReadFile(file.Name())
76		if err != nil {
77			return nil, 0, fmt.Errorf("read metrics log: %w", err)
78		}
79	
80		var batches [][]metrics.Sample
81		pos := int64(0)
82		for pos < int64(len(data)) {
83			remaining := int64(len(data)) - pos
84			if remaining < headerSize {
85				break // torn partial header
86			}
87			payloadLen := int64(binary.BigEndian.Uint32(data[pos : pos+4]))
88			if payloadLen <= 0 || payloadLen > maxPayload {
89				return nil, 0, corruption("corrupt metric frame header at offset %d", pos)
90			}
91			frameEnd := pos + headerSize + payloadLen
92			if frameEnd > int64(len(data)) {
93				break // header landed but its payload did not: torn tail
94			}
95			payload := data[pos+headerSize : frameEnd]
96			wantCRC := binary.BigEndian.Uint32(data[pos+4 : pos+headerSize])
97			if crc32.ChecksumIEEE(payload) != wantCRC {
98				return nil, 0, corruption("metric checksum mismatch at offset %d", pos)
99			}
100			batch, err := metrics.DecodeBatch(payload)
101			if err != nil {
102				return nil, 0, corruption("illegal metric frame payload at offset %d: %v", pos, err)
103			}
104			if len(batch) == 0 {
105				return nil, 0, corruption("empty metric batch frame at offset %d", pos)
106			}
107			for i := range batch {
108				normalized, err := metrics.Normalize(batch[i])
109				if err != nil {
110					return nil, 0, corruption("invalid metric sample in frame at offset %d: %v", pos, err)
111				}
112				batch[i] = normalized
113			}
114			batches = append(batches, batch)
115			pos = frameEnd
116		}
117		return batches, pos, nil
118	}
119	
120	// Append durably writes one batch: the frame is written and fsynced before the
121	// call returns. Any write or sync failure poisons the log so that this call
122	// and every later one fail until restart.
123	func (l *MetricsLog) Append(batch []metrics.Sample) (err error) {
124		payload, err := metrics.MarshalBatch(batch)
125		if err != nil {
126			return fmt.Errorf("encode metric batch: %w", err)
127		}
128		if len(payload) > maxPayload {
129			return fmt.Errorf("metric batch exceeds %d byte frame limit", maxPayload)
130		}
131	
132		frame := make([]byte, headerSize+len(payload))
133		binary.BigEndian.PutUint32(frame[0:4], uint32(len(payload)))
134		binary.BigEndian.PutUint32(frame[4:8], crc32.ChecksumIEEE(payload))
135		copy(frame[headerSize:], payload)
136	
137		l.mu.Lock()
138		defer l.mu.Unlock()
139		if l.poisoned {
140			return ErrPoisoned
141		}
142		defer func() {
143			if err != nil {
144				l.poisoned = true
145			}
146		}()
147	
148		if _, err = l.file.Write(frame); err != nil {
149			return fmt.Errorf("write metrics log: %w", err)
150		}
151		if err = l.file.Sync(); err != nil {
152			return fmt.Errorf("sync metrics log: %w", err)
153		}
154		return nil
155	}
156	
157	// Poisoned reports whether the metrics log has suffered a write failure.
158	func (l *MetricsLog) Poisoned() bool {
159		l.mu.Lock()
160		defer l.mu.Unlock()
161		return l.poisoned
162	}
163	
164	// Close releases the metrics log file. The shared directory lock is owned by
165	// the event log's Log and released there.
166	func (l *MetricsLog) Close() error {
167		l.mu.Lock()
168		defer l.mu.Unlock()
169		return l.file.Close()
170	}
