1	// Package metrics holds cumulative metric samples: their normalized content,
2	// batch ingestion with de-duplication, and the delta aggregation over aligned
3	// segments. Sample ids are independent of event ids.
4	package metrics
5	
6	import (
7		"errors"
8		"maps"
9		"math"
10		"sort"
11		"strconv"
12		"strings"
13		"sync"
14		"time"
15	
16		"github.com/cocosolocoder/signalroom/internal/events"
17	)
18	
19	// ValidationError reports that a sample failed normalization (or, during
20	// aggregation, that a query was invalid).
21	type ValidationError struct{ Reason string }
22	
23	func (e *ValidationError) Error() string { return e.Reason }
24	
25	// IsValidationError reports whether err is a metrics validation failure.
26	func IsValidationError(err error) bool {
27		var target *ValidationError
28		return errors.As(err, &target)
29	}
30	
31	// ConflictError reports an id clash with different content, a repeated id in
32	// one batch, or a series/time clash between different ids.
33	type ConflictError struct{ Reason string }
34	
35	func (e *ConflictError) Error() string { return e.Reason }
36	
37	// IsConflictError reports whether err is a metrics conflict.
38	func IsConflictError(err error) bool {
39		var target *ConflictError
40		return errors.As(err, &target)
41	}
42	
43	// Sample is one normalized cumulative counter reading. Labels carries the
44	// optional trimmed label set and is nil when the sample has none.
45	type Sample struct {
46		ID      string
47		Service string
48		Name    string
49		At      time.Time
50		Value   float64
51		Labels  map[string]string
52	}
53	
54	// Normalize applies the ingestion rules: trim surrounding whitespace from id,
55	// service, and metric name (their case is kept) and require each non-empty
56	// afterwards; require a non-zero instant; require a non-negative, finite
57	// value; and trim/validate labels with the same rules events use.
58	func Normalize(s Sample) (Sample, error) {
59		s.ID = strings.TrimSpace(s.ID)
60		s.Service = strings.TrimSpace(s.Service)
61		s.Name = strings.TrimSpace(s.Name)
62		if s.ID == "" || s.Service == "" || s.Name == "" || s.At.IsZero() {
63			return Sample{}, &ValidationError{Reason: "sample id, service, name, and timestamp are required"}
64		}
65		if !finiteNonNegative(s.Value) {
66			return Sample{}, &ValidationError{Reason: "value must be a non-negative, finite JSON number"}
67		}
68		labels, err := events.NormalizeLabels(s.Labels)
69		if err != nil {
70			return Sample{}, &ValidationError{Reason: err.Error()}
71		}
72		s.Labels = labels
73		return s, nil
74	}
75	
76	// finiteNonNegative rejects NaN, infinities (which JSON cannot carry anyway),
77	// and negative readings.
78	func finiteNonNegative(v float64) bool {
79		return !math.IsNaN(v) && !math.IsInf(v, 0) && v >= 0
80	}
81	
82	// seriesKey identifies one time series: a metric name within a service plus
83	// the complete label set. Names are compared case-sensitively after trimming.
84	type seriesKey struct {
85		service string
86		name    string
87		labels  string
88	}
89	
90	// BeforeCommit persists a batch of brand-new samples. It runs while the store
91	// lock is held and before the batch becomes visible, so a successful return
92	// guarantees the batch is durable and committed atomically.
93	type BeforeCommit func(persisted []Sample) error
94	
95	// Store is a concurrency-safe set of metric samples grouped into series. It
96	// accepts whole batches and reports retries of already-stored samples.
97	type Store struct {
98		mu     sync.RWMutex
99		byID   map[string]Sample
100		series map[seriesKey]*seriesState
101	}
102	
103	// NewStore returns an empty store.
104	func NewStore() *Store {
105		return &Store{
106			byID:   make(map[string]Sample),
107			series: make(map[seriesKey]*seriesState),
108		}
109	}
110	
111	// IngestResult counts how a batch was applied: Created samples are new,
112	// Replayed samples matched an existing sample with the same id and content.
113	type IngestResult struct {
114		Created  int
115		Replayed int
116	}
117	
118	// Ingest normalizes and validates every sample first, then checks the whole
119	// batch against stored samples and itself. Validation failures produce a
120	// ValidationError; duplicate ids with differing content, a repeated id within
121	// the batch, or a (series, time) clash between different ids produce a
122	// ConflictError. Nothing is stored when an error is returned.
123	//
124	// New samples are passed to beforeCommit for durable storage; only after it
125	// succeeds does the batch become visible, so concurrent readers see either the
126	// complete batch or none of it, and concurrent batches serialize so the whole
127	// batch either commits or fails.
128	func (s *Store) Ingest(batch []Sample, beforeCommit BeforeCommit) (IngestResult, error) {
129		normalized := make([]Sample, len(batch))
130		for i, sample := range batch {
131			norm, err := Normalize(sample)
132			if err != nil {
133				return IngestResult{}, err
134			}
135			normalized[i] = norm
136		}
137	
138		s.mu.Lock()
139		defer s.mu.Unlock()
140	
141		pendingID := make(map[string]struct{}, len(normalized))
142		pendingPoint := make(map[seriesKey]map[int64]string, len(normalized))
143		var created []Sample
144		var result IngestResult
145		for _, sample := range normalized {
146			if _, repeated := pendingID[sample.ID]; repeated {
147				return IngestResult{}, &ConflictError{Reason: "sample id repeats within batch"}
148			}
149			pendingID[sample.ID] = struct{}{}
150	
151			key := keyFor(sample)
152			if existing, ok := s.byID[sample.ID]; ok {
153				if !sameContent(existing, sample) {
154					return IngestResult{}, &ConflictError{Reason: "sample id already exists with different content"}
155				}
156				// An id retry must never mask another id's point.
157				if owner := s.series[key].pointOwner(sample.At); owner != "" && owner != sample.ID {
158					return IngestResult{}, &ConflictError{
159						Reason: "sample collides with a different sample of the same series at the same time"}
160				}
161				result.Replayed++
162				continue
163			}
164	
165			// A brand-new id must not claim a (series, time) point already stored
166			// under another id.
167			if owner := s.series[key].pointOwner(sample.At); owner != "" {
168				return IngestResult{}, &ConflictError{
169					Reason: "sample collides with a different sample of the same series at the same time"}
170			}
171			// Nor one introduced earlier in this same batch.
172			if owners := pendingPoint[key]; owners != nil {
173				if owner, dup := owners[sample.At.UnixNano()]; dup && owner != sample.ID {
174					return IngestResult{}, &ConflictError{
175						Reason: "sample collides with a different sample of the same series at the same time"}
176				}
177			}
178			created = append(created, sample)
179			result.Created++
180			if pendingPoint[key] == nil {
181				pendingPoint[key] = make(map[int64]string)
182			}
183			pendingPoint[key][sample.At.UnixNano()] = sample.ID
184		}
185	
186		if len(created) > 0 {
187			if beforeCommit != nil {
188				if err := beforeCommit(created); err != nil {
189					return IngestResult{}, err
190				}
191			}
192			for _, sample := range created {
193				s.byID[sample.ID] = sample
194				key := keyFor(sample)
195				state := s.series[key]
196				if state == nil {
197					state = &seriesState{labels: sample.Labels}
198					s.series[key] = state
199				}
200				state.add(sample)
201			}
202		}
203		return result, nil
204	}
205	
206	// Load inserts samples recovered from durable storage during startup. Every
207	// sample must already be normalized; a contradictory record is reported as a
208	// conflict so the caller can fail rather than mutate data.
209	func (s *Store) Load(sample Sample) error {
210		if _, err := Normalize(sample); err != nil {
211			return err
212		}
213		s.mu.Lock()
214		defer s.mu.Unlock()
215		key := keyFor(sample)
216		if existing, ok := s.byID[sample.ID]; ok {
217			if !sameContent(existing, sample) {
218				return &ConflictError{Reason: "sample id already exists with different content"}
219			}
220			return nil
221		}
222		if owner := s.series[key].pointOwner(sample.At); owner != "" {
223			return &ConflictError{Reason: "sample collides with a different sample of the same series at the same time"}
224		}
225		s.byID[sample.ID] = sample
226		state := s.series[key]
227		if state == nil {
228			state = &seriesState{labels: sample.Labels}
229			s.series[key] = state
230		}
231		state.add(sample)
232		return nil
233	}
234	
235	// keyFor builds the identity of a series from a normalized sample.
236	func keyFor(sample Sample) seriesKey {
237		return seriesKey{service: sample.Service, name: sample.Name, labels: labelsKey(sample.Labels)}
238	}
239	
240	// labelsKey renders a label set as a collision-free canonical string so two
241	// maps with the same complete set share a series regardless of iteration
242	// order. Name and value are each length-prefixed, which keeps values
243	// containing '=' or ';' from ever aliasing another set.
244	func labelsKey(labels map[string]string) string {
245		if len(labels) == 0 {
246			return ""
247		}
248		keys := make([]string, 0, len(labels))
249		for name := range labels {
250			keys = append(keys, name)
251		}
252		sort.Strings(keys)
253		var b strings.Builder
254		for _, name := range keys {
255			value := labels[name]
256			b.WriteString(strconv.Itoa(len(name)))
257			b.WriteByte(':')
258			b.WriteString(name)
259			b.WriteByte(',')
260			b.WriteString(strconv.Itoa(len(value)))
261			b.WriteByte(':')
262			b.WriteString(value)
263			b.WriteByte(';')
264		}
265		return b.String()
266	}
267	
268	// seriesState is one sorted run of (time, value, id) points sharing one
269	// label set.
270	type seriesState struct {
271		labels map[string]string
272		points []point
273	}
274	
275	type point struct {
276		at    time.Time
277		value float64
278		id    string
279	}
280	
281	// add inserts one point keeping the run ordered by time. Points at the same
282	// instant for one series are rejected upstream.
283	func (st *seriesState) add(sample Sample) {
284		p := point{at: sample.At, value: sample.Value, id: sample.ID}
285		idx := sort.Search(len(st.points), func(i int) bool {
286			return st.points[i].at.After(p.at)
287		})
288		st.points = append(st.points, point{})
289		copy(st.points[idx+1:], st.points[idx:])
290		st.points[idx] = p
291	}
292	
293	// pointOwner returns the id of the sample at exactly at, or "" when the point
294	// is absent. A nil receiver reports no owner.
295	func (st *seriesState) pointOwner(at time.Time) string {
296		if st == nil {
297			return ""
298		}
299		idx := sort.Search(len(st.points), func(i int) bool {
300			return !st.points[i].at.Before(at)
301		})
302		if idx < len(st.points) && st.points[idx].at.Equal(at) {
303			return st.points[idx].id
304		}
305		return ""
306	}
307	
308	// sameContent compares two normalized samples on their absolute instant,
309	// value, and label set. Numeric equality makes 1 and 1.0 identical; map
310	// comparison makes label key order irrelevant.
311	func sameContent(a, b Sample) bool {
312		return a.ID == b.ID &&
313			a.Service == b.Service &&
314			a.Name == b.Name &&
315			a.At.Equal(b.At) &&
