1	package httpapi
2	
3	import (
4		"encoding/json"
5		"errors"
6		"io"
7		"net/http"
8		"net/http/httptest"
9		"strings"
10		"sync"
11		"testing"
12	
13		"github.com/cocosolocoder/signalroom/internal/events"
14		"github.com/cocosolocoder/signalroom/internal/metrics"
15	)
16	
17	type fakeMetricStorage struct {
18		mu       sync.Mutex
19		failNext bool
20		poisoned bool
21		batches  [][]metrics.Sample
22	}
23	
24	func (f *fakeMetricStorage) Append(batch []metrics.Sample) error {
25		f.mu.Lock()
26		defer f.mu.Unlock()
27		if f.failNext {
28			f.poisoned = true
29			f.failNext = false
30			return errors.New("simulated metric write failure")
31		}
32		f.batches = append(f.batches, append([]metrics.Sample(nil), batch...))
33		return nil
34	}
35	
36	func (f *fakeMetricStorage) Poisoned() bool {
37		f.mu.Lock()
38		defer f.mu.Unlock()
39		return f.poisoned
40	}
41	
42	func newMetricsServer(t *testing.T, store *metrics.Store, mstore *fakeMetricStorage) *httptest.Server {
43		t.Helper()
44		if store == nil {
45			store = metrics.NewStore()
46		}
47		if mstore == nil {
48			mstore = &fakeMetricStorage{}
49		}
50		tl := events.NewTimeline()
51		eventStore := &fakeStorage{cursorKey: []byte("test-cursor-key-0123456789ab")}
52		server := httptest.NewServer(NewHandler(tl, eventStore, eventStore, WithMetrics(store, mstore)))
53		t.Cleanup(server.Close)
54		return server
55	}
56	
57	func metricsDo(t *testing.T, server *httptest.Server, method, path, body string) (int, map[string]any) {
58		t.Helper()
59		var reader io.Reader
60		if body != "" {
61			reader = strings.NewReader(body)
62		}
63		req, err := http.NewRequest(method, server.URL+path, reader)
64		if err != nil {
65			t.Fatal(err)
66		}
67		if body != "" {
68			req.Header.Set("Content-Type", "application/json")
69		}
70		resp, err := http.DefaultClient.Do(req)
71		if err != nil {
72			t.Fatal(err)
73		}
74		defer resp.Body.Close()
75		raw, err := io.ReadAll(resp.Body)
76		if err != nil {
77			t.Fatal(err)
78		}
79		var out map[string]any
80		if err := json.Unmarshal(raw, &out); err != nil {
81			t.Fatalf("decode %q (%d): %v", raw, resp.StatusCode, err)
82		}
83		return resp.StatusCode, out
84	}
85	
86	func postSamples(t *testing.T, server *httptest.Server, body string) map[string]any {
87		t.Helper()
88		status, out := metricsDo(t, server, http.MethodPost, "/metrics", body)
89		if status >= 400 {
90			t.Fatalf("POST /metrics %d: %v", status, out)
91		}
92		return out
93	}
94	
95	func TestPostMetricsCreatedAndReplayed(t *testing.T) {
96		server := newMetricsServer(t, nil, nil)
97		body := `{"samples":[
98			{"id":"s1","service":"gw","name":"requests","at":"2026-10-01T10:00:00Z","value":1},
99			{"id":"s2","service":"gw","name":"requests","at":"2026-10-01T10:00:01Z","value":2,"labels":{"env":"prod"}}
100		]}`
101		out := postSamples(t, server, body)
102		if int(number(out["created"])) != 2 || int(number(out["replayed"])) != 0 {
103			t.Fatalf("initial: %v", out)
104		}
105	
106		// Retry with 1.0 numeric equivalence.
107		retry := `{"samples":[
108			{"id":"s1","service":"gw","name":"requests","at":"2026-10-01T10:00:00Z","value":1.0},
109			{"id":"s2","service":"gw","name":"requests","at":"2026-10-01T18:00:01+08:00","value":2,"labels":{"env":"prod"}}
110		]}`
